<script setup>
import {ref} from 'vue'
import {api} from '../api'
const form=ref({username:'',name:'',email:'',password:''}),confirmPassword=ref(''),busy=ref(false),error=ref(''),notice=ref('')
async function submit(){error.value='';notice.value='';if(form.value.password!==confirmPassword.value){error.value='兩次密碼不同';return}busy.value=true;try{const r=await api('/auth/staff/register',{method:'POST',body:form.value});notice.value=r.message;form.value={username:'',name:'',email:'',password:''};confirmPassword.value=''}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><section class="staff-register"><h1>建立後台人員帳號</h1><p>新帳號沒有工作區權限，需等待最高管理員授權。</p><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><form @submit.prevent="submit"><label>帳號<input v-model.trim="form.username" required pattern="[A-Za-z0-9_]{4,50}" autocomplete="username" /></label><label>姓名<input v-model.trim="form.name" required maxlength="50" /></label><label>信箱<input v-model.trim="form.email" type="email" required maxlength="100" /></label><label>密碼<input v-model="form.password" type="password" required minlength="12" maxlength="72" autocomplete="new-password" /></label><label>確認密碼<input v-model="confirmPassword" type="password" required autocomplete="new-password" /></label><button :disabled="busy">建立待授權帳號</button></form><RouterLink to="/staff/login">返回後台登入</RouterLink></section></template>
<style scoped>.staff-register{max-width:460px;margin:40px auto;background:white;padding:28px;border-radius:16px}.staff-register form,.staff-register label{display:grid;gap:9px}.staff-register form{gap:16px;margin:20px 0}.staff-register input{padding:10px;border:1px solid #cadce9;border-radius:8px}.staff-register button{padding:12px;background:#17647d;color:white;border:0;border-radius:8px}</style>
